import { test, expect } from '@playwright/test';

test.describe('File Upload - Upload Button Disabled During Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <html>
        <body>
          <div id="upload-container">
            <input type="file" id="file-input" accept=".txt,.pdf,.doc" />
            <button id="upload-btn" type="button">Upload File</button>
            <div id="upload-status" style="margin-top: 10px;"></div>
            <div id="progress-bar" style="width: 0%; height: 20px; background-color: blue; margin-top: 10px;"></div>
          </div>
          <script>
            const fileInput = document.getElementById('file-input');
            const uploadBtn = document.getElementById('upload-btn');
            const statusDiv = document.getElementById('upload-status');
            const progressBar = document.getElementById('progress-bar');

            uploadBtn.addEventListener('click', async () => {
              if (fileInput.files.length === 0) {
                statusDiv.textContent = 'Please select a file';
                return;
              }

              uploadBtn.disabled = true;
              statusDiv.textContent = 'Uploading...';

              // Simulate file upload with progress
              for (let i = 0; i <= 100; i += 10) {
                progressBar.style.width = i + '%';
                await new Promise(resolve => setTimeout(resolve, 200));
              }

              uploadBtn.disabled = false;
              statusDiv.textContent = 'Upload complete';
              progressBar.style.width = '0%';
              fileInput.value = '';
            });
          </script>
        </body>
      </html>
    `);
  });

  test('should disable upload button when file upload starts', async ({ page }) => {
    const fileInput = page.locator('#file-input');
    const uploadBtn = page.getByRole('button', { name: 'Upload File' });

    // Create a test file
    await fileInput.setInputFiles({
      name: 'test.txt',
      mimeType: 'text/plain',
      buffer: Buffer.from('Test file content'),
    });

    // Verify button is enabled before upload
    await expect(uploadBtn).toBeEnabled();

    // Click upload button
    await uploadBtn.click();

    // Verify button is disabled during upload
    await expect(uploadBtn).toBeDisabled();
  });

  test('should re-enable upload button after file upload completes', async ({ page }) => {
    const fileInput = page.locator('#file-input');
    const uploadBtn = page.getByRole('button', { name: 'Upload File' });
    const statusDiv = page.locator('#upload-status');

    // Create a test file
    await fileInput.setInputFiles({
      name: 'document.txt',
      mimeType: 'text/plain',
      buffer: Buffer.from('Document content for testing'),
    });

    // Click upload button
    await uploadBtn.click();

    // Verify button is disabled during upload
    await expect(uploadBtn).toBeDisabled();

    // Wait for upload to complete
    await expect(statusDiv).toContainText('Upload complete', { timeout: 5000 });

    // Verify button is re-enabled after upload
    await expect(uploadBtn).toBeEnabled();
  });

  test('should show uploading status while button is disabled', async ({ page }) => {
    const fileInput = page.locator('#file-input');
    const uploadBtn = page.getByRole('button', { name: 'Upload File' });
    const statusDiv = page.locator('#upload-status');

    // Create a test file
    await fileInput.setInputFiles({
      name: 'data.txt',
      mimeType: 'text/plain',
      buffer: Buffer.from('Sample data'),
    });

    // Click upload button
    await uploadBtn.click();

    // Verify uploading status is shown
    await expect(statusDiv).toContainText('Uploading...');

    // Verify button is disabled while status shows uploading
    await expect(uploadBtn).toBeDisabled();
  });

  test('should prevent multiple simultaneous uploads', async ({ page }) => {
    const fileInput = page.locator('#file-input');
    const uploadBtn = page.getByRole('button', { name: 'Upload File' });

    // Create a test file
    await fileInput.setInputFiles({
      name: 'file.txt',
      mimeType: 'text/plain',
      buffer: Buffer.from('Content'),
    });

    // Click upload button
    await uploadBtn.click();

    // Verify button is disabled
    await expect(uploadBtn).toBeDisabled();

    // Try to click disabled button - should not trigger another upload
    const clickCount = await page.evaluate(() => {
      let count = 0;
      const btn = document.getElementById('upload-btn');
      const originalClick = btn.onclick;
      btn.addEventListener('click', () => {
        count++;
      });
      return count;
    });

    // Button should remain disabled and prevent interaction
    await expect(uploadBtn).toBeDisabled();
  });
});
